using System;using System.IO;using System.Text;using System.Net;using System.Net.Sockets;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;
internal static class WorkbenchHost {internal static string SmokeRoot="network-fixture";}
public sealed partial class WorkbenchWindow {
 internal Task<object> SpeedCall(string method,params object[] pairs){var p=new Dictionary<string,object>{{"deviceId","local"}};for(int i=0;i<pairs.Length;i+=2)p[(string)pairs[i]]=pairs[i+1];return NetworkSpeedRequest("networkSpeed."+method,p);}
 internal static void SpeedOrigin(string node,string url){SpeedOrigins[node]=url;}
}
internal sealed class SpeedHttpFixture:IDisposable {
 readonly TcpListener listener=new TcpListener(IPAddress.Loopback,0);internal int Code=200,Delay,Received,Requests;internal bool ExpectContinue;internal string Origin;
 internal SpeedHttpFixture(){listener.Start();Origin="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port;Accept();}
 async void Accept(){try{while(true){var c=await listener.AcceptTcpClientAsync();Serve(c);}}catch(ObjectDisposedException){}catch(SocketException){}}
 async void Serve(TcpClient c){using(c)try{var s=c.GetStream();var head=new StringBuilder();var one=new byte[1];while(head.Length<16384){int n=await s.ReadAsync(one,0,1);if(n==0)return;head.Append((char)one[0]);if(head.Length>=4&&head.ToString().EndsWith("\r\n\r\n",StringComparison.Ordinal))break;}string h=head.ToString();ExpectContinue|=h.IndexOf("Expect: 100-continue",StringComparison.OrdinalIgnoreCase)>=0;int length=0;foreach(var line in h.Split(new[]{"\r\n"},StringSplitOptions.None))if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(line.Substring(15).Trim(),out length);int read=0;var buffer=new byte[4096];while(read<length){int n=await s.ReadAsync(buffer,0,Math.Min(buffer.Length,length-read));if(n==0)break;read+=n;}Interlocked.Add(ref Received,read);Interlocked.Increment(ref Requests);if(Delay>0)await Task.Delay(Delay);var response=Encoding.ASCII.GetBytes("HTTP/1.1 "+Code+" Fixture\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");await s.WriteAsync(response,0,response.Length);}catch(IOException){}catch(SocketException){}catch(ObjectDisposedException){}}
 public void Dispose(){listener.Stop();}
}
internal static class NetworkSpeedTests {
 static int failures;static object Get(object value,string property){return value.GetType().GetProperty(property).GetValue(value,null);}static void Check(bool value,string name){Console.WriteLine((value?"PASS ":"FAIL ")+name);if(!value)failures++;}
 static async Task Run(bool live){var host=new WorkbenchWindow();var run=await host.SpeedCall("start","cap",20);var id=(string)Get(run,"id");if(live){foreach(string node in new[]{"cf","den","ams"}){var result=await host.SpeedCall("request","id",id,"node",node,"direction","up","size",131072,"timeout",7000);Console.WriteLine("LIVE "+node+" "+new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result));}await host.SpeedCall("cancel","id",id);return;}
 using(var fixture=new SpeedHttpFixture()){WorkbenchWindow.SpeedOrigin("cf",fixture.Origin);var result=await host.SpeedCall("request","id",id,"node","cf","direction","up","size",150000,"timeout",3000);Check((bool)Get(result,"ok")&&fixture.Received==150000,"upload sends its complete reserved body and only reports HTTP success");Check(!fixture.ExpectContinue,"upload does not wait for optional 100-continue handshake");fixture.Code=405;result=await host.SpeedCall("request","id",id,"node","cf","direction","up","size",1024,"timeout",3000);Check(!(bool)Get(result,"ok")&&(string)Get(result,"reason")=="http"&&Convert.ToInt32(Get(result,"status"))==405,"POST refusal remains a diagnostic failure, not a throughput sample");fixture.Code=200;fixture.Delay=500;result=await host.SpeedCall("request","id",id,"node","cf","direction","up","size",1024,"timeout",100);Check(!(bool)Get(result,"ok")&&(string)Get(result,"reason")=="timeout","upload timeout remains failure");fixture.Delay=0;result=await host.SpeedCall("request","id",id,"node","cf","direction","up","size",1024,"timeout",3000);Check((bool)Get(result,"ok"),"timed-out transfer releases reservation lock for a retry");}await host.SpeedCall("cancel","id",id);}
 static int Main(string[] args){try{Run(args.Length>0&&args[0]=="--live").GetAwaiter().GetResult();return failures==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
